l64_label = (hex_char . hex_char) $!_hex_char_error %_l64_count;
        l64 = (l64_label . (':' >!_l64_sep_error . l64_label)+
              ) $!_hex_char_error >_l64_init %_l64_exit;

        l32 = ipv4_addr %_ipv4_addr_write;
        # END

